// Node test: the JS engine reproduces the Python numbers in tests/fixtures/engine_fixture.json, generated by
// `python scripts/make_engine_fixture.py --write` from wireframe.py, scene_math.py and camera.py.
// Run: node web/static/engine.test.mjs
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { buildShape, centreOf, rotationMatrix, transformVertices, physicsStep, viewMatrix, projectionMatrix, project,
  orbit, zoom, parseObj, toObj, parseJson, toJson, CAMERA_DEFAULTS } from './engine.js';
import { edgesFromFaces } from './geometry.js';

const FIX = JSON.parse(readFileSync(new URL('../../tests/fixtures/engine_fixture.json', import.meta.url)));
const close = (a, b, tol, what) => assert.ok(Math.abs(a - b) <= tol * Math.max(1, Math.abs(b)), `${what}: js ${a} vs py ${b}`);
let checks = 0, worst = 0;

// 1. every shape generator: same vertex count and order, same faces; vertices are float32 in both
for (const s of FIX.shapes) {
  const js = buildShape(s.kind, s.name, s.params || [], FIX.letters);
  const what = `${s.kind} ${s.name} ${JSON.stringify(s.params)}`;
  assert.equal(js.vertices.length, s.vertices.length, `${what}: vertex count`);
  assert.deepEqual(js.faces, s.faces, `${what}: faces`);
  js.vertices.forEach((v, i) => v.forEach((x, k) => {
    worst = Math.max(worst, Math.abs(x - s.vertices[i][k]));
    close(x, s.vertices[i][k], 1e-6, `${what} v${i}[${k}]`);
  }));
  checks++;
}

// 2. SceneObject transforms (scene_math.transform_vertices)
for (const t of FIX.transforms) {
  const shape = buildShape('basic', t.name);
  rotationMatrix(t.rotation).forEach((row, i) => row.forEach((x, j) => close(x, t.matrix[i][j], 1e-12, `R[${i}][${j}]`)));
  const out = transformVertices(shape.vertices, centreOf(shape.vertices), t.scale, t.rotation, t.position);
  out.forEach((v, i) => v.forEach((x, k) => close(x, t.vertices[i][k], 1e-9, `${t.name} transformed v${i}[${k}]`)));
  checks++;
}

// 3. physics: 150 steps of Scene.update_physics
const [p0, v0, w0] = FIX.physics.start;
const obj = { position: [...p0], velocity: [...v0], rotation: [0, 0, 0], angularVelocity: [...w0] };
FIX.physics.traj.forEach((row, t) => {
  physicsStep(obj, FIX.physics.dt);
  [...obj.position, ...obj.velocity, ...obj.rotation].forEach((x, k) => close(x, row[k], 1e-9, `physics step ${t}[${k}]`));
});
assert.ok(FIX.physics.traj.some(r => r[4] > 0) && Math.min(...FIX.physics.traj.map(r => r[1])) >= 0, 'ball bounced');
checks++;

// 4. camera: view / projection matrices, projected pixels, orbit and wheel zoom
for (const c of FIX.camera.cases) {
  viewMatrix(c.cam).forEach((row, i) => row.forEach((x, j) => close(x, c.view[i][j], 1e-9, `view[${i}][${j}]`)));
  projectionMatrix(c.cam, c.width, c.height).forEach((row, i) => row.forEach((x, j) => close(x, c.proj[i][j], 1e-9, `proj[${i}][${j}]`)));
  const { xy, depth } = project(FIX.camera.probe, c.cam, c.width, c.height);
  xy.forEach((p, i) => { close(p[0], c.xy[i][0], 1e-8, `px${i}`); close(p[1], c.xy[i][1], 1e-8, `py${i}`); close(depth[i], c.depth[i], 1e-9, `depth${i}`); });
  checks++;
}
assert.deepEqual({ ...CAMERA_DEFAULTS }, FIX.camera.defaults);
const o = orbit(structuredClone(CAMERA_DEFAULTS), -37, 75), z = zoom(structuredClone(CAMERA_DEFAULTS), 360);
close(o.azimuth, FIX.camera.orbit.azimuth, 1e-12, 'orbit az'); close(o.elevation, FIX.camera.orbit.elevation, 1e-12, 'orbit el');
close(z.distance, FIX.camera.zoom.distance, 1e-12, 'zoom'); checks++;

// 5. file round trips and edges
const tor = buildShape('parametric', 'Mobius Strip', [8, 4]);
const back = parseObj(toObj(tor.vertices, tor.faces));
const pos0 = a => a.map(v => v.map(x => x + 0)); // -0 is written as "0"
assert.deepEqual(back.faces, tor.faces); assert.deepEqual(pos0(back.vertices), pos0(tor.vertices));
const j = parseJson(toJson(tor.vertices, tor.faces));
assert.deepEqual(j.faces, tor.faces);
assert.equal(edgesFromFaces(buildShape('basic', 'Dodecahedron').faces).length, 30, 'dodecahedron has 30 edges');
assert.throws(() => buildShape('text', 'HELLO', [], FIX.letters), /No supported characters/);
checks++;

console.log(`engine: ${checks} checks passed (${FIX.shapes.length} shapes, max vertex diff ${worst.toExponential(1)}, ` +
  `${FIX.transforms.length} transforms, ${FIX.physics.traj.length} physics steps, ${FIX.camera.cases.length} cameras)`);
